'use strict';
(function(){
 const R=ReadinessModel,E=escapeHTML;
 let notebook=R.empty(),storageKey='',storageError='';
 const panel=document.createElement('section');panel.id='readiness';panel.className='panel readiness';
 $('advanced-planning').before(panel);
 const input=(id,label,type='text',extra='')=>`<label for="ops-${id}">${label}</label><input id="ops-${id}" type="${type}" ${extra} required>`;
 const select=(id,label,options)=>`<label for="ops-${id}">${label}</label><select id="ops-${id}">${options.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select>`;
 const date=new Date().toISOString().slice(0,10);
 panel.innerHTML=`<div class="section-heading"><div><div class="eyebrow">EVIDENCE / READINESS / EVENT DAY</div><h2>From estimate to a reviewable plan</h2></div><button class="button lime" id="start-tour">Start guided walkthrough</button></div>
 <div class="ops-body"><p>Keep evidence and event records with this scenario. Records save on this browser and travel with scenario JSON exports. Names are self-reported; this is not an authenticated team workspace.</p><p id="ops-storage" role="status"></p><div id="ops-summary" class="evidence-strip"></div>
 <nav class="planning-tabs" aria-label="Readiness sections"><a href="#ops-evidence">Evidence</a><a href="#ops-validation">Accuracy</a><a href="#ops-access">Access checks</a><a href="#ops-tasks">Tasks</a><a href="#ops-incidents">Event day</a><a href="#ops-reviews">Review history</a></nav>
 <details id="ops-evidence" open><summary>1 · Sources and freshness</summary><p>Record the source and collection date of parking capacity, entrance details and restrictions. Recording a source does not independently verify it or change simulation inputs.</p><div id="ops-counts"></div><form id="ops-evidence-form" class="ops-form">${select('kind','Evidence type',[['parking','Parking capacity'],['entrance','Entrance / path'],['restriction','Road restriction'],['traffic','Traffic survey']])}${input('value','Finding / measured value','text','maxlength="300"')}${input('source','Source or survey reference','text','maxlength="200"')}${input('collected','Collected on','date',`value="${date}" max="${date}"`)}<button class="button dark">Record evidence</button></form><div id="ops-evidence-list"></div></details>
 <details id="ops-validation"><summary>2 · Prediction accuracy</summary><p>Compare predictions with independent event observations for the same location and time interval. Do not reuse background counts used to tune the model. Traffic uses vehicles/hour; parking uses occupied spaces. Results measure these samples only.</p><form id="ops-observation-form" class="ops-form">${select('metric','Measure',[['traffic','Traffic (vehicles/hour)'],['parking','Parking (occupied spaces)']])}${input('location','Road / parking location and interval','text','maxlength="200"')}${input('predicted','Prediction recorded before observation','number','min="0" max="100000" step="any"')}${input('actual','Observed value','number','min="0" max="100000" step="any"')}${input('obsSource','Independent observation source','text','maxlength="200"')}${input('obsDate','Observation date','date',`value="${date}" max="${date}"`)}<label class="ops-check"><input id="ops-independent" type="checkbox" required> This observation was not used to tune this prediction.</label><button class="button dark">Add comparison</button></form><div id="ops-accuracy" aria-live="polite"></div><div id="ops-observations-list"></div></details>
 <details id="ops-access"><summary>3 · Pedestrian, accessible and emergency access</summary><p>Record a site check for an actual path, crossing, accessible parking space or emergency entrance. The mapped route remains unverified until responsible personnel assess the complete route.</p><form id="ops-check-form" class="ops-form">${select('accessType','Access item',[['Step-free entrance','Step-free entrance'],['Accessible parking','Accessible parking'],['Pedestrian crossing','Pedestrian crossing'],['Emergency entrance','Emergency entrance'],['Emergency route','Emergency route']])}${input('accessLocation','Exact entrance / path / location','text','maxlength="200"')}${select('accessStatus','Site-check outcome',[['unverified','Needs verification'],['pass','Checked — no issue recorded'],['blocked','Blocked / issue found']])}${input('checker','Checked by / responsible person','text','maxlength="100"')}${input('accessEvidence','Evidence reference and restrictions','text','maxlength="300"')}${input('accessDate','Check date','date',`value="${date}" max="${date}"`)}<button class="button dark">Record access check</button></form><div id="ops-checks-list"></div></details>
 <details id="ops-tasks"><summary>4 · Readiness tasks and owners</summary><form id="ops-task-form" class="ops-form">${input('task','Task or arrangement','text','maxlength="200"')}${input('owner','Assigned to','text','maxlength="100"')}${input('due','Due date','date',`value="${date}"`)}<button class="button dark">Add task</button></form><div id="ops-tasks-list"></div></details>
 <details id="ops-incidents"><summary>5 · Event-day updates</summary><p>Manual updates, with local recording timestamps. These records do not change model inputs or road closures; apply changes in the simulation separately.</p><form id="ops-incident-form" class="ops-form">${select('incidentType','Update type',[['Road closure','Road closure'],['Parking full','Parking full'],['Crowding','Crowding'],['Other','Other']])}${input('incidentLocation','Location','text','maxlength="200"')}${input('incidentNote','What happened / action needed','text','maxlength="300"')}${input('reporter','Reported by','text','maxlength="100"')}<button class="button dark">Log update</button></form><div id="ops-incidents-list" aria-live="polite"></div></details>
 <details id="ops-reviews"><summary>6 · Review history</summary><p>Record a reviewer, decision and comments for the current inputs. Changes to the plan make previous reviews historical. Decisions are self-reported, not official authorization.</p><form id="ops-review-form" class="ops-form">${input('reviewer','Reviewer name','text','maxlength="100"')}${select('decision','Decision',[['Draft','Draft'],['Changes requested','Changes requested'],['Reviewed','Reviewed'],['Approved by named reviewer','Approved by named reviewer']])}${input('comment','Comment / required changes','text','maxlength="500"')}<button class="button dark">Record review of current plan</button></form><div id="ops-reviews-list"></div></details></div>`;
 const keyFor=v=>'urbanpulse-readiness:'+JSON.stringify([v.name,v.date,v.venue]);
 const fingerprint=v=>{const {readiness,...rest}=v;return JSON.stringify(rest);};
 // A short deterministic identifier detects changed plan inputs, not identity or authorization.
 const revision=v=>{let h=2166136261;for(const c of fingerprint(v))h=Math.imul(h^c.charCodeAt(0),16777619);return (h>>>0).toString(16);};
 function save(){snapshot.readiness=notebook;try{localStorage.setItem(storageKey,JSON.stringify(notebook));storageError='';}catch{storageError='Browser save unavailable. Export the scenario JSON to keep these records.';}render();}
 function value(id){return $('ops-'+id).value.trim();}
 function number(id){return Number(value(id));}
 function add(kind,row){try{const next={...notebook,[kind]:[...notebook[kind],{...row,recorded:new Date().toISOString()}]};notebook=R.validate(next);save();notify('Record saved with this scenario.');}catch(e){notify(e.message);}}
 const on=(id,fn)=>$(id).addEventListener('submit',event=>{event.preventDefault();if(!run())return;fn();});
 on('ops-evidence-form',()=>add('evidence',{kind:value('kind'),value:value('value'),source:value('source'),date:value('collected')}));
 on('ops-observation-form',()=>add('observations',{metric:value('metric'),location:value('location'),predicted:number('predicted'),actual:number('actual'),source:value('obsSource'),date:value('obsDate'),independent:true,revision:revision(snapshot)}));
 on('ops-check-form',()=>add('checks',{item:value('accessType'),location:value('accessLocation'),status:value('accessStatus'),person:value('checker'),source:value('accessEvidence'),date:value('accessDate')}));
 on('ops-task-form',()=>add('tasks',{task:value('task'),owner:value('owner'),due:value('due'),done:false}));
 on('ops-incident-form',()=>add('incidents',{type:value('incidentType'),location:value('incidentLocation'),note:value('incidentNote'),person:value('reporter'),resolved:false}));
 on('ops-review-form',()=>add('reviews',{person:value('reviewer'),decision:value('decision'),comment:value('comment'),revision:revision(snapshot)}));
 function list(kind,html){const target=$('ops-'+kind+'-list');target.innerHTML=notebook[kind].length?notebook[kind].map((r,i)=>`<article class="ops-record">${html(r)}<small>Recorded ${E(new Date(r.recorded).toLocaleString())}</small><div class="planning-buttons">${kind==='tasks'?`<button class="button light" data-toggle="${i}" data-kind="tasks">${r.done?'Reopen task':'Mark complete'}</button>`:kind==='incidents'?`<button class="button light" data-toggle="${i}" data-kind="incidents">${r.resolved?'Reopen incident':'Mark resolved'}</button>`:''}<button class="button light" data-remove="${i}" data-kind="${kind}">Remove record</button></div></article>`).join(''):'<p class="form-note">No records yet.</p>';}
 function render(){
  const k=keyFor(snapshot);if(storageKey!==k){storageKey=k;try{notebook=R.validate(snapshot.readiness||JSON.parse(localStorage.getItem(k)||'null')||undefined);}catch{notebook=R.empty();storageError='Could not restore saved records. Import a scenario backup if available.';}}
  snapshot.readiness=notebook;
  $('ops-storage').textContent=storageError||'Notebook saved on this device. Export a scenario to transfer it. Cloud snapshots are copies, not live collaboration.';
  $('ops-summary').textContent=`${notebook.evidence.length} evidence records · ${notebook.observations.length} validation samples · ${notebook.checks.filter(c=>c.status==='blocked').length} access issues · ${notebook.tasks.filter(t=>!t.done).length} open tasks · ${notebook.incidents.filter(i=>!i.resolved).length} active updates. No independent verification is implied.`;
  const counts=Object.entries(snapshot.trafficCounts||{});$('ops-counts').innerHTML=`<p><b>${counts.length} uploaded background counts</b> / ${UrbanModel.roads.length} segments. Uncovered segments use synthetic traffic. Map snapshot: ${E(CityData.downloaded)}.</p>`+(counts.length?'<div class="ops-scroll"><table><tr><th>Road</th><th>Source</th><th>Collected</th><th>Freshness</th></tr>'+counts.map(([id,c])=>`<tr><td>${E(id)}</td><td>${E(c.source)}</td><td>${E(c.date)}</td><td>${E(R.age(c.date))}</td></tr>`).join('')+'</table></div>':'');
  list('evidence',r=>`<h4>${E(r.kind)} · ${E(r.value)}</h4><p>${E(r.source)} · ${E(r.date)} · ${E(R.age(r.date))}</p>`);
  $('ops-accuracy').innerHTML=['traffic','parking'].map(metric=>{const a=R.accuracy(notebook.observations,metric);return `<div class="planning-result"><strong>${metric==='traffic'?'Traffic':'Parking'}</strong>${a?`<span>${a.n} independent sample(s) · mean absolute error ${a.mae.toFixed(1)} ${metric==='traffic'?'vehicles/h':'spaces'} · weighted absolute percentage error ${a.wape===null?'unavailable (zero observed total)':a.wape.toFixed(1)+'%'} · bias ${a.bias.toFixed(1)}</span>`:'<span>No independent observations yet. Accuracy has not been established.</span>'}</div>`;}).join('')+'<p class="form-note">Positive bias means overprediction. Errors are not a safety score or proof of accuracy across the city. Samples may cover different plan revisions.</p>';
  list('observations',r=>`<h4>${E(r.metric)} · ${E(r.location)}</h4><p>Predicted ${r.predicted} / observed ${r.actual} · ${E(r.source)} · ${E(r.date)} · plan ${E(r.revision)}</p>`);
  list('checks',r=>`<h4>${E(r.item)} · ${E(r.status)}</h4><p>${E(r.location)} · ${E(r.person)} · ${E(r.source)} · ${E(r.date)} · ${E(R.age(r.date))}</p>`);
  list('tasks',r=>`<h4>${r.done?'Complete':'Open'} · ${E(r.task)}</h4><p>Owner: ${E(r.owner)} · due ${E(r.due)}${!r.done&&r.due<date?' · OVERDUE':''}</p>`);
  list('incidents',r=>`<h4>${r.resolved?'Resolved':'Active'} · ${E(r.type)}</h4><p>${E(r.location)} · ${E(r.note)} · ${E(r.person)}</p>`);
  list('reviews',r=>`<h4>${E(r.decision)} · ${E(r.person)}</h4><p>${E(r.comment)}</p><p>${r.revision===revision(snapshot)?'Applies to current model inputs':'Historical — model inputs have changed'} · plan ${E(r.revision)}</p>`);
 }
 panel.addEventListener('click',event=>{const link=event.target.closest('a[href^="#ops-"]');if(link){const section=document.querySelector(link.getAttribute('href'));if(section)section.open=true;}const b=event.target.closest('[data-remove],[data-toggle]');if(!b)return;const kind=b.dataset.kind;if(b.hasAttribute('data-remove'))notebook[kind].splice(+b.dataset.remove,1);else{const r=notebook[kind][+b.dataset.toggle],key=kind==='tasks'?'done':'resolved';r[key]=!r[key];r.recorded=new Date().toISOString();}save();});
 const old={...PlanningUI};PlanningUI.read=()=>{const v=old.read();const nextKey=keyFor({name:$('event-name').value,date:$('date').value,venue:$('venue').value});return {...v,...(nextKey===storageKey?{readiness:notebook}:{})};};
 PlanningUI.fill=v=>{old.fill(v);storageKey=keyFor(v);try{notebook=R.validate(v.readiness||JSON.parse(localStorage.getItem(storageKey)||'null')||undefined);}catch{notebook=R.empty();}};
 PlanningUI.render=()=>{old.render();render();};
 PlanningUI.report=()=>old.report()+`<section><h2>Evidence, validation and readiness</h2><p>${E($('ops-summary').textContent)}</p>${$('ops-accuracy').innerHTML}${['evidence','checks','tasks','incidents','reviews'].map(k=>`<h3>${k}</h3>${$('ops-'+k+'-list').innerHTML.replace(/<button[\s\S]*?<\/button>/g,'')}`).join('')}<p>Self-reported records. No authenticated approval or independently verified access is implied.</p></section>`;
 const tour=document.createElement('dialog');tour.className='ops-tour';tour.setAttribute('aria-labelledby','tour-title');tour.innerHTML='<div class="eyebrow" id="tour-progress"></div><h2 id="tour-title"></h2><p id="tour-copy"></p><div class="planning-buttons"><button class="button light" id="tour-back">Back</button><button class="button lime" id="tour-next">Next</button><button class="button light" id="tour-close">Close walkthrough</button></div>';document.body.append(tour);
 const steps=[['Plan an event','Set attendance, date, arrival window and parking supply. Start with the existing sample event; the walkthrough does not replace your work.','event-form'],['Run and compare','Run the simulation, then compare original A with proposed B. Try shuttles or a road closure and explain the change.','comparison'],['Identify the assumptions','Open Sources and freshness. Upload background counts where available and record the source of capacity and access details.','ops-evidence'],['Check actual access','Record pedestrian, step-free and emergency access findings after a site visit. A route drawn on the map is not a verified accessible route.','ops-access'],['Measure prediction error','Add independent observations for the same location and interval as your predictions. Begin with one real event.','ops-validation'],['Prepare and present','Assign readiness tasks, record review comments, then create the impact report. Export the scenario JSON to continue on another device.','report']];let tourIndex=0;
 function tourStep(){const [title,copy,target]=steps[tourIndex];$('tour-progress').textContent=`STEP ${tourIndex+1} / ${steps.length}`;$('tour-title').textContent=title;$('tour-copy').textContent=copy;$('tour-back').disabled=tourIndex===0;$('tour-next').textContent=tourIndex===steps.length-1?'Finish':'Next';const el=$(target);if(el?.tagName==='DETAILS')el.open=true;window.AppPages?.reveal(el);el?.scrollIntoView({behavior:'smooth',block:'center'});}
 $('start-tour').onclick=()=>{tourIndex=0;tour.showModal();tourStep();};$('tour-back').onclick=()=>{tourIndex--;tourStep();};$('tour-next').onclick=()=>{if(++tourIndex===steps.length)tour.close();else tourStep();};$('tour-close').onclick=()=>tour.close();
 const welcome=document.createElement('div');welcome.className='ops-welcome';welcome.innerHTML='<strong>New to UrbanPulse?</strong><span>Follow one event from planning inputs to an impact report.</span><button class="button light" id="welcome-tour">Show me how</button><a href="#readiness">Open readiness workspace ↓</a>';$('workspace').prepend(welcome);$('welcome-tour').onclick=()=>$('start-tour').click();
 render();
})();

